/**
 * Apple's root CA certificate, DER-encoded, base64'd for embedding directly
 * in compiled source rather than as a separate asset file — this repo's
 * `nest-cli.json` has no asset-copy step, so a file dropped next to the
 * source wouldn't survive into `dist/`. This is a public certificate (not a
 * secret), downloaded from https://www.apple.com/certificateauthority/
 * (Apple Root CA - G3, valid until 2039) — required by
 * `@apple/app-store-server-library`'s `SignedDataVerifier` to validate the
 * certificate chain on every signed transaction/notification it decodes.
 * Re-download from the same URL if Apple ever rotates this root.
 */
const APPLE_ROOT_CA_G3_BASE64 =
  '';

export const APPLE_ROOT_CERTIFICATES: Buffer[] = [Buffer.from(APPLE_ROOT_CA_G3_BASE64, 'base64')];
